using System.Globalization;

namespace SWH2.Core;

/// <summary>
/// A known release of SteamWorld Heist 2.exe. Exe mods are written for the Steam build; every other build has an
/// address map (SWH2.Core/Maps/&lt;id&gt;.map, generated by tools/re/build_map.py from both exes) that translates
/// Steam RVAs to its own. Only addresses inside a mapped range (functions that are the same code in both builds,
/// data they reference) can be translated.
/// </summary>
public sealed class GameBuild
{
    public static readonly GameBuild Steam = new("steam", "Steam", "F1C07F0343A5A4F7512C0A167BCF91C90555D12FFBEF0B6CF24EB54B25C5A611", null);
    public static readonly GameBuild Gog = Load("gog", "GOG");

    public static IReadOnlyList<GameBuild> All { get; } = [Steam, Gog];

    public static GameBuild? FromSha256(string sha256) => All.FirstOrDefault(b => b.Sha256 == sha256);

    readonly (uint Start, uint End, int Delta)[]? _ranges; // null = identity (the Steam build)

    GameBuild(string id, string name, string sha256, (uint, uint, int)[]? ranges)
    {
        Id = id;
        Name = name;
        Sha256 = sha256;
        _ranges = ranges;
    }

    public string Id { get; }
    /// <summary>Store name shown to players.</summary>
    public string Name { get; }
    /// <summary>SHA-256 of the original exe of this build.</summary>
    public string Sha256 { get; }

    /// <summary>The RVA in this build of <paramref name="steamRva"/>, or null when it has no known counterpart.</summary>
    public uint? TryMap(uint steamRva)
    {
        if (_ranges == null) return steamRva;
        int lo = 0, hi = _ranges.Length - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            var r = _ranges[mid];
            if (steamRva < r.Start) hi = mid - 1;
            else if (steamRva >= r.End) lo = mid + 1;
            else return (uint)(steamRva + r.Delta);
        }
        return null;
    }

    public override string ToString() => Name;

    static GameBuild Load(string id, string name)
    {
        using var stream = typeof(GameBuild).Assembly.GetManifestResourceStream($"SWH2.Maps.{id}.map")
            ?? throw new InvalidOperationException($"Address map {id}.map is missing from SWH2.Core.");
        using var reader = new StreamReader(stream);
        string? sha = null;
        var ranges = new List<(uint, uint, int)>();
        while (reader.ReadLine() is { } line)
        {
            var p = line.Split(' ');
            if (line.StartsWith("#") || p.Length < 2) continue;
            if (p[0] == id) sha = p[1];
            else if (p.Length == 3 && p[0] is not ("steam" or "stamp"))
            {
                int delta = p[2].StartsWith("-") ? -int.Parse(p[2].Substring(1), NumberStyles.HexNumber) : int.Parse(p[2], NumberStyles.HexNumber);
                ranges.Add((uint.Parse(p[0], NumberStyles.HexNumber), uint.Parse(p[1], NumberStyles.HexNumber), delta));
            }
        }
        return new(id, name, sha ?? throw new InvalidOperationException($"{id}.map has no exe hash."), ranges.ToArray());
    }
}
